-- One-time seed of static master data reverse-engineered from
-- 'Tracking_การกรอก Supply Daily_WK35.xlsx' (Mas โรงงาน / Mas P19 Cus /
-- Mas sku ตัวแทน sheets). This data does not get re-uploaded weekly like
-- the other 5 data sources -- it is seeded once here and can be edited
-- afterwards by an admin via the Settings page (see mas_* RLS policies:
-- select is open, writes require is_admin()).

create table mas_factories (
  id bigint generated always as identity primary key,
  plant_code text not null,
  warehouse_name text not null,
  -- Nullable: the source sheet has a second block of supplementary factory
  -- rows carrying only plant_code/warehouse_name/vendor_group, with these
  -- three left genuinely blank (not a parsing artifact -- see plan notes).
  class_price text,
  vendor_group text, -- Column1
  class_price_ladder text,
  species text -- Column3 (Chicken/Pork)
);
create index mas_factories_plant_code_idx on mas_factories (plant_code);

