-- All 6 tables: open select (every signed-in/anon session may read master
-- data to drive the Supply Daily checks), writes admin-only.
alter table mas_factories enable row level security;
create policy mas_factories_select on mas_factories for select to anon, authenticated using (true);
create policy mas_factories_admin_write on mas_factories for all to authenticated using (is_admin()) with check (is_admin());
grant select on mas_factories to anon, authenticated;
grant insert, update, delete on mas_factories to authenticated;

